input.command:
cat > /tmp/checktel.exp <<'EOF'
set timeout 6
spawn telnet 127.0.0.1 6665
expect {
  -re "(?i)login:" { puts "\nSEEN_PROMPT_WITHOUT_INPUT"; exp_continue }
  timeout { puts "\nNO_PROMPT_WITHOUT_INPUT" }
}
send "\r"
set timeout 6
expect {
  -re "(?i)login:" { puts "\nSEEN_PROMPT_AFTER_ENTER" }
  timeout { puts "\nNO_PROMPT_AFTER_ENTER" }
}
close
EOF
timeout 25 expect -f /tmp/checktel.exp 2>&1 | tr -d '\r' | tail -20
